<?php
if (!defined('ABSPATH')) exit;
final class WPFI_Admin {
 private $repo,$scheduler,$importer,$logger; public function __construct($r,$s,$i,$l){$this->repo=$r;$this->scheduler=$s;$this->importer=$i;$this->logger=$l;add_action('admin_menu',[$this,'menu']);add_action('admin_post_wpfi_save_feed',[$this,'save']);add_action('admin_post_wpfi_delete_feed',[$this,'delete']);add_action('admin_post_wpfi_run_feed',[$this,'run']);}
 public function menu(){add_submenu_page('woocommerce','XML/CSV Feed Importer','XML/CSV Feed Importer','manage_woocommerce','wpfi-feeds',[$this,'page']);}
 private function can(){return current_user_can('manage_woocommerce');}private function url($a=[]){return add_query_arg(array_merge(['page'=>'wpfi-feeds'],$a),admin_url('admin.php'));}private function input($n,$v,$type='text'){return '<input class="regular-text" type="'.$type.'" name="'.esc_attr($n).'" value="'.esc_attr($v??'').'">';}private function pairs($a){$o=[];foreach((array)$a as $k=>$v)$o[]=$k.'='.$v;return implode("\n",$o);}private function parse($x){$o=[];foreach(preg_split('/\r\n|\r|\n/',(string)$x) as $l){$p=explode('=', $l,2);if(count($p)===2&&trim($p[0]))$o[sanitize_text_field(trim($p[0]))]=sanitize_text_field(trim($p[1]));}return $o;}
 public function page(){if(!$this->can())return;$action=sanitize_key($_GET['action']??'list');if($action==='edit'||$action==='new')$this->edit();else$this->list();}
 private function list(){echo '<div class="wrap"><h1>XML/CSV Product Feeds</h1><p><a class="button button-primary" href="'.esc_url($this->url(['action'=>'new'])).'">Add feed</a></p><table class="widefat striped"><thead><tr><th>Name</th><th>Format</th><th>URL</th><th>Schedule</th><th>Actions</th></tr></thead><tbody>';foreach($this->repo->all() as $f){echo '<tr><td>'.esc_html($f['name']).'</td><td>'.esc_html(strtoupper($f['format']??'xml')).'</td><td>'.esc_html($f['url']).'</td><td>'.esc_html($f['frequency']).'</td><td><a href="'.esc_url($this->url(['action'=>'edit','id'=>$f['id']])).'">Edit</a> | <a href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=wpfi_run_feed&id='.$f['id']),'wpfi_run_'.$f['id'])).'">Run now</a> | <a onclick="return confirm(\'Delete feed?\')" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=wpfi_delete_feed&id='.$f['id']),'wpfi_delete_'.$f['id'])).'">Delete</a></td></tr>';}echo '</tbody></table></div>';}
 private function edit(){ $id=sanitize_text_field($_GET['id']??'');$f=wp_parse_args($id?$this->repo->get($id):[],$this->repo->defaults());$a=$f['auth'];$c=$f['csv'];echo '<div class="wrap"><h1>'.($id?'Edit':'Add').' feed</h1><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="wpfi_save_feed"><input type="hidden" name="id" value="'.esc_attr($f['id']).'">';wp_nonce_field('wpfi_save_feed');echo '<table class="form-table">';foreach([['name','Name'],['slug','Slug'],['url','Feed URL'],['product_xpath','Product XPath'],['identifier_field','Identifier field'],['variation_xpath','Variation XPath'],['variation_identifier_field','Variation identifier']] as $x)echo '<tr><th>'.esc_html($x[1]).'</th><td>'.$this->input($x[0],$f[$x[0]]).'</td></tr>';echo '<tr><th>Format</th><td><select name="format"><option value="csv" '.selected($f['format'],'csv',false).'>CSV</option><option value="xml" '.selected($f['format'],'xml',false).'>XML</option></select></td></tr><tr><th>Enabled</th><td><input type="checkbox" name="enabled" value="1" '.checked($f['enabled'],1,false).'></td></tr><tr><th>Frequency</th><td><select name="frequency">';foreach(['wpfi_15m'=>'15 minutes','wpfi_30m'=>'30 minutes','hourly'=>'Hourly','twicedaily'=>'Twice daily','daily'=>'Daily','wpfi_6h'=>'6 hours','weekly'=>'Weekly'] as $k=>$v)echo '<option value="'.$k.'" '.selected($f['frequency'],$k,false).'>'.$v.'</option>';echo '</select></td></tr></table><h2>CSV settings</h2><table class="form-table"><tr><th>Delimiter</th><td>'.$this->input('csv_delimiter',$c['delimiter']??',').'</td></tr><tr><th>Enclosure</th><td>'.$this->input('csv_enclosure',$c['enclosure']??'"').'</td></tr><tr><th>Header row</th><td><input type="checkbox" name="csv_header" value="1" '.checked($c['has_header']??1,1,false).'></td></tr></table><h2>CSV field mapping</h2><p>Use one line per mapping: WooCommerce field=CSV column header.</p><textarea name="map" rows="9" class="large-text code">'.esc_textarea($this->pairs($f['map'])).'</textarea><h2>Custom attributes</h2><p>Use one line per mapping: Attribute name=CSV column header.</p><textarea name="attributes" rows="4" class="large-text code">'.esc_textarea($this->pairs($f['attributes'])).'</textarea><h2>Authentication</h2><select name="auth_type"><option value="none">None</option><option value="api_key">API key header</option><option value="bearer">Bearer token</option><option value="basic">Basic username/password</option><option value="query" selected>Query-string credentials</option><option value="custom">Custom headers</option></select><p>API key header name</p>'.$this->input('api_key_name',$a['api_key_name']??'X-API-Key').'<p>API key</p>'.$this->input('api_key',$a['api_key']??'','password').'<p>Bearer token</p>'.$this->input('bearer_token',$a['bearer_token']??'','password').'<p>Username</p>'.$this->input('username',$a['username']??'').'<p>Password</p>'.$this->input('password',$a['password']??'','password').'<p>Query parameters, one key=value per line</p><textarea name="query_params" rows="5" class="large-text code">'.esc_textarea($this->pairs($a['query_params']??[])).'</textarea><p>Custom headers, one Header=value per line</p><textarea name="headers" rows="5" class="large-text code">'.esc_textarea($this->pairs($a['headers']??[])).'</textarea><p><button class="button button-primary">Save feed</button></p></form></div>';}
 public function save(){if(!$this->can()||!check_admin_referer('wpfi_save_feed'))wp_die('Permission denied.');$f=$this->repo->defaults();$f['id']=sanitize_text_field($_POST['id']??'')?:wp_generate_uuid4();foreach(['name','slug','product_xpath','identifier_field','variation_xpath','variation_identifier_field'] as $k)$f[$k]=sanitize_text_field(wp_unslash($_POST[$k]??''));$f['url']=esc_url_raw(wp_unslash($_POST['url']??''));$f['format']=sanitize_key($_POST['format']??'csv');$f['enabled']=!empty($_POST['enabled']);$f['frequency']=sanitize_key($_POST['frequency']??'daily');$f['map']=$this->parse(wp_unslash($_POST['map']??''));$f['attributes']=$this->parse(wp_unslash($_POST['attributes']??''));$f['csv']=['delimiter'=>sanitize_text_field($_POST['csv_delimiter']??','),'enclosure'=>sanitize_text_field($_POST['csv_enclosure']??'"'),'has_header'=>!empty($_POST['csv_header'])?1:0];$f['auth']=['type'=>sanitize_key($_POST['auth_type']??'none'),'api_key_name'=>sanitize_text_field($_POST['api_key_name']??'X-API-Key'),'api_key'=>sanitize_text_field($_POST['api_key']??''),'bearer_token'=>sanitize_text_field($_POST['bearer_token']??''),'username'=>sanitize_text_field($_POST['username']??''),'password'=>sanitize_text_field($_POST['password']??''),'query_params'=>$this->parse(wp_unslash($_POST['query_params']??'')),'headers'=>$this->parse(wp_unslash($_POST['headers']??''))];$this->repo->save($f);$this->scheduler->sync();wp_safe_redirect($this->url());exit;}
 public function delete(){$id=sanitize_text_field($_GET['id']??'');if(!$this->can()||!$id||!check_admin_referer('wpfi_delete_'.$id))wp_die('Permission denied.');$this->repo->delete($id);$this->scheduler->sync();wp_safe_redirect($this->url());exit;}public function run(){$id=sanitize_text_field($_GET['id']??'');if(!$this->can()||!$id||!check_admin_referer('wpfi_run_'.$id))wp_die('Permission denied.');$f=$this->repo->get($id);if($f)$this->importer->import($f);wp_safe_redirect($this->url());exit;}
}
